create table if not exists public.stazz_public_messages(id bigint generated by default as identity primary key,display_name text not null check(char_length(display_name) between 1 and 40),message text not null check(char_length(message) between 1 and 500),created_at timestamptz not null default now());alter table public.stazz_public_messages enable row level security;drop policy if exists "Anyone can read STAZZ public wall" on public.stazz_public_messages;create policy "Anyone can read STAZZ public wall" on public.stazz_public_messages for select to anon,authenticated using(true);drop policy if exists "Anyone can post to STAZZ public wall" on public.stazz_public_messages;create policy "Anyone can post to STAZZ public wall" on public.stazz_public_messages for insert to anon,authenticated with check(char_length(display_name) between 1 and 40 and char_length(message) between 1 and 500);alter table public.stazz_public_messages replica identity full;do $$ begin alter publication supabase_realtime add table public.stazz_public_messages; exception when duplicate_object then null; end $$;